steps.command:
rm <scratch>-before.txt; S=<scratch>; python3 - "$S" <<'EOF'
import os, sys
from pathlib import Path
S = Path(sys.argv[1]); sys.path.insert(0, str(S / ".hold/convergence-prompt-audit/x9-round2")); import void_patterns as v
hits = {"MAPPING": [], "PHRASES": []}; n = 0
for d, _, fs in os.walk(S / "j2/x9/root"):
    for f in fs:
        p = Path(d) / f
        try: t = p.read_text(errors="ignore")
        except OSError: continue
        n += 1
        for k in hits:
            if getattr(v, k).search(t): hits[k].append(str(p.relative_to(S / "j2/x9/root")))
print(n, "files;", {k: len(x) for k, x in hits.items()}, {k: x[:5] for k, x in hits.items()})
EOF
